// Tazele arayüzünün (ContentView + Theme) HTML kopyası; banners.html ve tazele-shot için ortak.
// Semboller SF Symbols'ten alınmış maske görselleridir (data URI); renkler Theme.swift ve macOS sistem renkleridir.
// Gösterilen veri bu Mac'in gerçek `brew outdated` / `npm outdated -g` / uygulama taraması çıktısıdır.
(function(){
var S={"sync": [124.0, 121.0, "data:image/png;base64,"], "search": [120.0, 116.0, "data:image/png;base64,"], "refresh": [105.0, 124.0, "data:image/png;base64,"], "chev": [79.0, 107.0, "data:image/png;base64,"], "check": [119.0, 106.0, "data:image/png;base64,"], "box": [126.0, 125.0, "data:image/png;base64,"], "win": [141.0, 110.0, "data:image/png;base64,"], "spark": [119.0, 124.0, "data:image/png;base64,"], "cube": [127.0, 130.0, "data:image/png;base64,"], "down": [117.0, 117.0, "data:image/png;base64,"], "dots": [109.0, 36.0, "data:image/png;base64,"], "arrow": [121.0, 96.0, "data:image/png;base64,"]};
function sym(n,fs,color,css){var s=S[n],w=(s[0]*fs/100).toFixed(2),h=(s[1]*fs/100).toFixed(2);
 return '<i style="display:inline-block;flex:none;width:'+w+'px;height:'+h+'px;background:'+color+';-webkit-mask:url('+s[2]+') center/100% 100% no-repeat;'+(css||'')+'"></i>';}
window.tazelePanel=function(dark,o){
 o=o||{};
 var ink=dark?'rgba(255,255,255,.88)':'rgba(0,0,0,.85)',sec=dark?'rgba(255,255,255,.55)':'rgba(0,0,0,.5)',ter=dark?'rgba(255,255,255,.26)':'rgba(0,0,0,.25)',
  ov=function(a){return dark?'rgba(255,255,255,'+a+')':'rgba(0,0,0,'+a+')'},
  top='#21C7A8',bot='#0A7585',brand='linear-gradient(135deg,'+top+','+bot+')',
  panel=dark?'#2B2B2D':'#F0F0F1',
  card=dark?'rgba(255,255,255,.065)':'rgba(255,255,255,.66)',
  cardBd=dark?'rgba(255,255,255,.13)':'rgba(255,255,255,.9)',
  tint={orange:dark?'#FF9F0A':'#FF9500',purple:dark?'#BF5AF2':'#AF52DE',teal:dark?'#40C8E0':'#30B0C7',red:dark?'#FF453A':'#FF3B30'},
  blue=dark?'#0A84FF':'#007AFF',
  f='font-family:-apple-system,\'SF Pro Text\',system-ui;',fr='font-family:ui-rounded,\'SF Pro Rounded\',-apple-system;',fm='font-family:ui-monospace,\'SF Mono\',Menlo;';
 var cardCss=function(el){return 'border-radius:14px;background:'+card+';border:.75px solid '+cardBd+';box-shadow:0 '+(el?4:1)+'px '+(el?10:2)+'px rgba(0,0,0,'+(el?(dark?.4:.12):(dark?.2:.06))+');'};
 var check=function(on){return on?'<span style="width:17px;height:17px;border-radius:50%;background:'+brand+';display:grid;place-items:center;flex:none">'+sym('check',8,'#fff')+'</span>':'<span style="width:17px;height:17px;border-radius:50%;box-sizing:border-box;border:1.3px solid '+ov(.3)+';flex:none"></span>'};
 var pill=function(a,b){return '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 7px;border-radius:99px;background:'+ov(.06)+';'+fm+'font-size:10.5px;line-height:13px;letter-spacing:.1px;white-space:nowrap"><span style="color:'+sec+'">'+a+'</span>'+sym('arrow',7,ter)+'<b style="color:'+(dark?top:bot)+';font-weight:600">'+b+'</b></span>'};
 var row=function(it,kind){var base='display:flex;align-items:center;gap:10px;padding:6px 12px;';
  if(kind==='app')return '<div style="'+base+'"><span style="font-size:12.5px;line-height:16px;color:'+ink+'">'+it[0]+'</span><span style="flex:1;min-width:8px"></span>'+pill(it[1],it[2])+'<span style="font-size:11.5px;color:'+blue+'">Aç</span></div>';
  return '<div style="'+base+'">'+check(1)+'<span style="font-size:12.5px;line-height:16px;color:'+ink+'">'+it[0]+'</span><span style="flex:1;min-width:8px"></span>'+pill(it[1],it[2])+'</div>'};
 var D=[
 {kind:'formula',title:'Homebrew (formül)',short:'Formül',tint:'orange',sym:'box',open:0,items:[['gh','2.102.0','2.103.3']]},
 {kind:'cask',title:'Homebrew (cask)',short:'Cask',tint:'purple',sym:'win',open:1,items:[['android-platform-tools','37.0.0','37.0.1'],['iina','1.4.4','1.5.0'],['keka','1.6.7','1.6.8'],['utm','4.7.5','5.0.8']]},
 {kind:'app',title:'Uygulamalar (kendi güncelleyicisi)',short:'Uygulama',tint:'teal',sym:'spark',open:1,items:[['Dia','1.54.2','1.55.1'],['OBS','32.2.2','33.0.0'],['ChatGPT','26.1021.31345','26.1027.30824']]},
 {kind:'npm',title:'npm (global)',short:'npm',tint:'red',sym:'cube',open:0,items:[['playwright-core','1.63.0','1.64.1']]}
];
 var total=0;D.forEach(function(g){total+=g.items.length});
 var sel=0;D.forEach(function(g){if(g.kind!=='app')sel+=g.items.length});
 var dots=D.map(function(g){return '<span style="display:inline-flex;align-items:center;gap:4px;font-size:10.5px;color:'+sec+'"><i style="width:6px;height:6px;border-radius:50%;background:'+tint[g.tint]+'"></i>'+g.short+' '+g.items.length+'</span>'}).join('');
 var tile=function(g){var c=tint[g.tint];return '<span style="width:26px;height:26px;border-radius:7px;flex:none;display:grid;place-items:center;background:linear-gradient(180deg,color-mix(in srgb,'+c+' 82%,#fff),'+c+')">'+sym(g.sym,12,'#fff')+'</span>'};
 var sections=D.map(function(g){
  var head='<div style="display:flex;align-items:center;gap:10px;padding:9px 12px">'+tile(g)+'<b style="font-size:12.5px;font-weight:600;color:'+ink+'">'+g.title+'</b><span style="'+fr+'font-size:10.5px;font-weight:600;padding:1.5px 6px;border-radius:99px;background:'+ov(.08)+';color:'+ink+';line-height:13px">'+g.items.length+'</span><span style="flex:1"></span>'+sym('chev',9,ter,'transform:rotate('+(g.open?90:0)+'deg)')+(g.kind!=='app'?check(1):'')+'</div>';
  var body=g.open?'<div style="height:1px;background:'+ov(.07)+'"></div><div>'+g.items.map(function(i){return row(i,g.kind)}).join('')+'</div>':'';
  return '<div style="'+cardCss(0)+'">'+head+body+'</div>'}).join('<div style="height:8px"></div>');
 return '<div style="'+f+'width:400px;box-sizing:border-box;padding:16px;display:flex;flex-direction:column;gap:12px;border-radius:14px;background:'+panel+';border:1px solid '+ov(.12)+';color:'+ink+';letter-spacing:0;line-height:1.2">'+
  '<div style="display:flex;align-items:center;gap:11px"><span style="width:38px;height:38px;border-radius:10px;background:'+brand+';display:grid;place-items:center;box-shadow:0 2px 6px rgba(10,117,133,.4)">'+sym('sync',17,'#fff')+'</span>'+
   '<div><div style="'+fr+'font-size:17px;font-weight:700;letter-spacing:-.2px;line-height:20px">Tazele</div><div style="font-size:11.5px;letter-spacing:.1px;color:'+sec+';line-height:14px;margin-top:1px">'+total+' güncelleme bekliyor</div></div><span style="flex:1"></span>'+
   '<span style="width:28px;height:28px;border-radius:50%;background:'+ov(.07)+';display:grid;place-items:center">'+sym('refresh',12,ink)+'</span></div>'+
  '<div style="'+cardCss(1)+'display:flex;align-items:center;gap:14px;padding:10px 14px"><span style="'+fr+'font-size:40px;font-weight:700;letter-spacing:-1.2px;line-height:48px;background:'+brand+';-webkit-background-clip:text;color:transparent">'+total+'</span><div style="display:flex;flex-direction:column;gap:5px"><b style="font-size:12.5px;font-weight:600;letter-spacing:.1px">güncelleme hazır</b><div style="display:flex;flex-wrap:wrap;gap:3px 10px">'+dots+'</div></div></div>'+
  '<div style="display:flex;align-items:center;gap:7px;padding:7px 10px;border-radius:9px;background:'+ov(.06)+'">'+sym('search',11.5,sec)+'<span style="font-size:12.5px;color:'+ter+'">Ara</span></div>'+
  '<div style="padding:1px 0">'+sections+'</div>'+
  '<div style="display:flex;align-items:center;justify-content:center;gap:7px;padding:11px 0;border-radius:12px;background:'+brand+';box-shadow:0 3px 8px rgba(10,117,133,.35);color:#fff;font-size:13.5px;font-weight:600">'+sym('down',13.5,'#fff')+'<span>'+sel+' güncellemeyi yükle</span></div>'+
  '<div style="display:flex;align-items:center;justify-content:space-between;font-size:11px;letter-spacing:.15px;color:'+ter+'"><span>Son tarama 9:38</span><span style="display:inline-flex;align-items:center;gap:9px"><span style="display:inline-block;width:11px;height:13px;background:'+ter+';-webkit-mask:url(data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2011%2013%27%3E%3Cpath%20d%3D%27M2.5%205.5V4a3%203%200%200%201%206%200v1.5h.3c.7%200%201.2.5%201.2%201.2v4.6c0%20.7-.5%201.2-1.2%201.2H2.2C1.5%2012.5%201%2012%201%2011.3V6.7c0-.7.5-1.2%201.2-1.2zm1.4%200h3.2V4a1.6%201.6%200%200%200-3.2%200z%27%2F%3E%3C%2Fsvg%3E) center/100% 100% no-repeat"></span>'+sym('dots',11,ter)+'</span></div></div>';
};
window.tazeleSym=sym;
})();
